-- ANGELCARE HomeService Experience & Mission Design OS — UMZ1
-- Sovereign Service Foundation, Standards & Enterprise Command
begin;
select pg_advisory_xact_lock(84746001);
set local lock_timeout='5min';
set local statement_timeout='0';
create extension if not exists pgcrypto;

do $$ begin
  if to_regclass('public.missions') is null then raise exception 'CARELINK baseline missing: public.missions'; end if;
end $$;
create or replace function public.hsd_touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=timezone('utc',now()); return new; end$$;
create or replace function public.hsd_immutable_guard() returns trigger language plpgsql as $$begin raise exception 'Immutable HomeService Design record'; end$$;

create table if not exists public.hsd_service_families(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,description_fr text not null default '',icon_key text not null default 'sparkles',sort_order int not null default 100,status text not null default 'draft',created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_service_categories(id uuid primary key default gen_random_uuid(),tenant_id text not null,family_id uuid not null references public.hsd_service_families(id) on delete restrict,code text not null,commercial_name_fr text not null,operational_name_fr text not null,description_fr text not null default '',carelink_service_type text,audience text not null default 'both' check(audience in('b2c','b2b','both')),cities text[] not null default '{}',languages text[] not null default '{}',beneficiary_profiles text[] not null default '{}',mission_formats text[] not null default '{}',status text not null default 'draft',version_number int not null default 1,created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_service_subcategories(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,code text not null,name_fr text not null,description_fr text not null default '',status text not null default 'draft',sort_order int not null default 100,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code));
create table if not exists public.hsd_service_references(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,subcategory_id uuid references public.hsd_service_subcategories(id) on delete set null,code text not null,name_fr text not null,status text not null default 'draft',current_version int not null default 1,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_service_versions(id uuid primary key default gen_random_uuid(),tenant_id text not null,service_reference_id uuid not null references public.hsd_service_references(id) on delete restrict,version_number int not null,status text not null default 'draft',definition jsonb not null default '{}',effective_from date,effective_to date,approved_by text,approved_at timestamptz,created_at timestamptz not null default timezone('utc',now()),unique(tenant_id,service_reference_id,version_number));
create table if not exists public.hsd_dossier_sections(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete cascade,section_code text not null,title_fr text not null,purpose_fr text not null,status text not null default 'draft',completion_percent int not null default 0 check(completion_percent between 0 and 100),blocker_count int not null default 0,owner_role text not null default 'À affecter',sort_order int not null,approved_by text,approved_at timestamptz,updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,section_code));
create table if not exists public.hsd_doctrine_rules(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,code text not null,kind text not null,severity text not null default 'important',title_fr text not null,description_fr text not null,mandatory boolean not null default true,blocking boolean not null default false,applicability jsonb not null default '{}',required_evidence text[] not null default '{}',escalation_route text,status text not null default 'draft',version_number int not null default 1,effective_from date,effective_to date,created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code,version_number));
create table if not exists public.hsd_capacity_rules(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,minimum_hours numeric(6,2) not null,maximum_hours numeric(6,2) not null,maximum_consecutive_days int not null default 14,maximum_non_consecutive_days int not null default 60,earliest_start_time time not null default '06:00',latest_end_time time not null default '23:00',max_beneficiaries_per_agent int not null default 1,minimum_agents int not null default 1,backup_required boolean not null default false,supervisor_required boolean not null default false,lead_time_hours int not null default 24,night_allowed boolean not null default false,weekend_allowed boolean not null default true,holiday_allowed boolean not null default true,allowed_cities text[] not null default '{}',conditions jsonb not null default '{}',status text not null default 'draft',updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id),check(maximum_hours>=minimum_hours));
create table if not exists public.hsd_service_options(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,code text not null,name_fr text not null,description_fr text not null default '',option_type text not null check(option_type in('feature','topup','upsell')),included_by_default boolean not null default false,pricing_basis text not null default 'per_mission',unit_price_dh numeric(12,2) not null default 0,cost_amount_dh numeric(12,2) not null default 0,minimum_quantity numeric(12,2) not null default 0,maximum_quantity numeric(12,2) not null default 999,eligibility_rule text,customer_visible boolean not null default true,sort_order int not null default 100,status text not null default 'draft',updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code));
create table if not exists public.hsd_materials(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,description_fr text not null default '',provider_scope text not null default 'angelcare',unit text not null default 'unit',status text not null default 'draft',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_service_material_links(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete cascade,material_id uuid not null references public.hsd_materials(id) on delete restrict,required boolean not null default false,minimum_quantity numeric(12,2) not null default 0,notes text,status text not null default 'draft',unique(tenant_id,category_id,material_id));
create table if not exists public.hsd_competencies(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,family text not null default 'general',description_fr text not null default '',evidence_type text not null default 'declaration',renewal_months int,status text not null default 'draft',created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_service_competency_rules(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete cascade,competency_id uuid not null references public.hsd_competencies(id) on delete restrict,required_level text not null default 'operational',mandatory boolean not null default true,minimum_experience_months int not null default 0,certification_required boolean not null default false,status text not null default 'draft',unique(tenant_id,category_id,competency_id));
create table if not exists public.hsd_risk_controls(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,description_fr text not null default '',severity text not null default 'important',trigger_conditions text[] not null default '{}',preventive_controls text[] not null default '{}',required_evidence text[] not null default '{}',stop_work boolean not null default false,escalation_route text not null default 'Dispatch / sécurité',category_codes text[] not null default '{}',status text not null default 'draft',created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_safeguards(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete cascade,risk_id uuid references public.hsd_risk_controls(id) on delete set null,code text not null,title_fr text not null,control_type text not null default 'preventive',required_evidence text[] not null default '{}',blocking_if_missing boolean not null default false,status text not null default 'draft',unique(tenant_id,category_id,code));
create table if not exists public.hsd_activity_library(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,description_fr text not null default '',block_type text not null default 'activity',objective_codes text[] not null default '{}',category_codes text[] not null default '{}',age_min_months int,age_max_months int,min_minutes int not null,max_minutes int not null,energy_level text not null default 'moderate',location_type text not null default 'indoor',materials text[] not null default '{}',competency_codes text[] not null default '{}',risk_codes text[] not null default '{}',evidence_codes text[] not null default '{}',repetition_limit_per_day int not null default 1,status text not null default 'draft',version_number int not null default 1,created_by text,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code,version_number),check(max_minutes>=min_minutes));
create table if not exists public.hsd_checklist_templates(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,code text not null,name_fr text not null,purpose_fr text not null default '',status text not null default 'draft',version_number int not null default 1,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code,version_number));
create table if not exists public.hsd_checklist_template_items(id uuid primary key default gen_random_uuid(),tenant_id text not null,template_id uuid not null references public.hsd_checklist_templates(id) on delete cascade,code text not null,phase text not null,label_fr text not null,item_type text not null default 'boolean',mandatory boolean not null default false,evidence_required boolean not null default false,blocking_if_failed boolean not null default false,sort_order int not null default 100,status text not null default 'draft',unique(tenant_id,template_id,code));
create table if not exists public.hsd_report_templates(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,code text not null,name_fr text not null,purpose_fr text not null default '',status text not null default 'draft',version_number int not null default 1,updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code,version_number));
create table if not exists public.hsd_report_template_fields(id uuid primary key default gen_random_uuid(),tenant_id text not null,template_id uuid not null references public.hsd_report_templates(id) on delete cascade,code text not null,section_fr text not null,label_fr text not null,field_type text not null,required boolean not null default false,option_values text[] not null default '{}',sort_order int not null default 100,status text not null default 'draft',unique(tenant_id,template_id,code));
create table if not exists public.hsd_price_books(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,currency_code text not null default 'MAD',status text not null default 'draft',effective_from date,effective_to date,approved_by text,approved_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,code));
create table if not exists public.hsd_price_entries(id uuid primary key default gen_random_uuid(),tenant_id text not null,category_id uuid not null references public.hsd_service_categories(id) on delete restrict,price_book_id uuid references public.hsd_price_books(id) on delete restrict,code text not null,customer_segment text not null default 'all',pricing_basis text not null,minimum_quantity numeric(12,2) not null default 1,unit_price_dh numeric(12,2) not null,cost_amount_dh numeric(12,2) not null default 0,margin_floor_percent numeric(7,2) not null default 0,effective_from date not null,effective_to date,status text not null default 'draft',updated_by text,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,category_id,code,effective_from));
create table if not exists public.hsd_option_sets(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,name_fr text not null,description_fr text not null default '',status text not null default 'active',unique(tenant_id,code));
create table if not exists public.hsd_option_values(id uuid primary key default gen_random_uuid(),tenant_id text not null,option_set_id uuid not null references public.hsd_option_sets(id) on delete cascade,code text not null,label_fr text not null,description_fr text not null default '',sort_order int not null default 100,status text not null default 'active',metadata jsonb not null default '{}',unique(tenant_id,option_set_id,code));
create table if not exists public.hsd_saved_views(id uuid primary key default gen_random_uuid(),tenant_id text not null,user_id text not null,name_fr text not null,workspace_code text not null,visibility text not null default 'personal',configuration jsonb not null default '{}',locked boolean not null default false,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table if not exists public.hsd_comments(id uuid primary key default gen_random_uuid(),tenant_id text not null,entity_type text not null,entity_id text not null,section_code text,body text not null,visibility text not null default 'team',status text not null default 'open',created_by text not null,created_at timestamptz not null default timezone('utc',now()),resolved_by text,resolved_at timestamptz);
create table if not exists public.hsd_attachments(id uuid primary key default gen_random_uuid(),tenant_id text not null,entity_type text not null,entity_id text not null,classification text not null,file_name text not null,storage_reference text not null,checksum text,mime_type text,size_bytes bigint,created_by text not null,created_at timestamptz not null default timezone('utc',now()));
create table if not exists public.hsd_approvals(id uuid primary key default gen_random_uuid(),tenant_id text not null,entity_type text not null,entity_id text not null,entity_label text not null,approval_type text not null,requested_by text not null,requested_at timestamptz not null default timezone('utc',now()),assigned_role text not null,status text not null default 'pending',consequence_summary text not null default '',blocker_summary text[] not null default '{}',evidence_count int not null default 0,decision text,decision_reason text,decided_by text,decided_at timestamptz);
create table if not exists public.hsd_audit_events(id uuid primary key default gen_random_uuid(),tenant_id text not null,actor_id text not null,actor_label text not null,action text not null,entity_type text not null,entity_id text not null,entity_label text not null,from_state text,to_state text,reason text,consequence text,correlation_id text not null,payload jsonb not null default '{}',created_at timestamptz not null default timezone('utc',now()));
create table if not exists public.hsd_outbox_events(id uuid primary key default gen_random_uuid(),tenant_id text not null,event_type text not null,aggregate_type text not null,aggregate_id text not null,correlation_id text not null,payload jsonb not null default '{}',status text not null default 'pending',attempts int not null default 0,available_at timestamptz not null default timezone('utc',now()),created_at timestamptz not null default timezone('utc',now()),processed_at timestamptz);
create table if not exists public.hsd_configuration_imports(id uuid primary key default gen_random_uuid(),tenant_id text not null,import_type text not null,file_name text not null,checksum text not null,status text not null default 'staged',total_rows int not null default 0,valid_rows int not null default 0,invalid_rows int not null default 0,duplicate_rows int not null default 0,committed_rows int not null default 0,commit_failures jsonb not null default '[]',source_content text not null default '',headers text[] not null default '{}',created_by text not null,created_at timestamptz not null default timezone('utc',now()),committed_by text,committed_at timestamptz,commit_reason text,rollback_reason text,rolled_back_by text,rolled_back_at timestamptz,unique(tenant_id,checksum));
create table if not exists public.hsd_configuration_import_rows(id uuid primary key default gen_random_uuid(),tenant_id text not null,import_id uuid not null references public.hsd_configuration_imports(id) on delete cascade,row_number int not null,raw_data jsonb not null,normalized_data jsonb not null default '{}',status text not null default 'staged',issues text[] not null default '{}',duplicate_key text,commit_error text,committed_at timestamptz,unique(tenant_id,import_id,row_number));
create table if not exists public.hsd_configuration_import_issues(id uuid primary key default gen_random_uuid(),tenant_id text not null,import_id uuid not null references public.hsd_configuration_imports(id) on delete cascade,row_number int,issue_code text not null,severity text not null,message_fr text not null,field_name text,created_at timestamptz not null default timezone('utc',now()));
create table if not exists public.hsd_configuration_import_changes(change_order bigserial primary key,id uuid not null default gen_random_uuid() unique,tenant_id text not null,import_id uuid not null references public.hsd_configuration_imports(id) on delete cascade,import_row_id uuid references public.hsd_configuration_import_rows(id) on delete cascade,row_number int not null,table_name text not null,record_id text not null,record_key text not null,operation text not null check(operation in('insert','update')),before_data jsonb,after_data jsonb not null,created_at timestamptz not null default timezone('utc',now()),rolled_back_by text,rolled_back_at timestamptz);
create table if not exists public.hsd_permissions(code text primary key,name_fr text not null,description_fr text not null,risk_level text not null default 'standard',created_at timestamptz not null default timezone('utc',now()));

create or replace view public.hsd_v_service_families as select f.*,count(c.id)::int category_count,coalesce(round(avg(r.overall_readiness)),0)::int readiness_score from public.hsd_service_families f left join public.hsd_service_categories c on c.family_id=f.id left join lateral (select 0::numeric overall_readiness) r on true group by f.id;
create or replace view public.hsd_v_doctrine_rules as select d.*,c.code category_code,c.commercial_name_fr category_name from public.hsd_doctrine_rules d join public.hsd_service_categories c on c.id=d.category_id;
create or replace view public.hsd_v_capacity_rules as select d.*,c.code category_code,c.commercial_name_fr category_name from public.hsd_capacity_rules d join public.hsd_service_categories c on c.id=d.category_id;
create or replace view public.hsd_v_activity_library as select a.* from public.hsd_activity_library a;
create or replace view public.hsd_v_competencies as select k.*,count(r.id)::int category_count,coalesce(array_agg(c.code) filter(where c.code is not null),array[]::text[]) category_codes from public.hsd_competencies k left join public.hsd_service_competency_rules r on r.competency_id=k.id left join public.hsd_service_categories c on c.id=r.category_id group by k.id;
create or replace view public.hsd_v_risk_controls as select r.*,case r.severity when 'blocking' then 5 when 'critical' then 4 when 'important' then 3 when 'attention' then 2 else 1 end severity_rank from public.hsd_risk_controls r;
create or replace view public.hsd_v_category_materials as select l.*,m.code material_code,m.name_fr material_name,m.name_fr,c.code category_code from public.hsd_service_material_links l join public.hsd_materials m on m.id=l.material_id join public.hsd_service_categories c on c.id=l.category_id;
create or replace view public.hsd_v_checklist_templates as select t.*,c.code category_code,c.commercial_name_fr category_name,(select count(*) from public.hsd_checklist_template_items i where i.template_id=t.id)::int item_count from public.hsd_checklist_templates t join public.hsd_service_categories c on c.id=t.category_id;
create or replace view public.hsd_v_report_templates as select t.*,c.code category_code,c.commercial_name_fr category_name,(select count(*) from public.hsd_report_template_fields i where i.template_id=t.id)::int field_count from public.hsd_report_templates t join public.hsd_service_categories c on c.id=t.category_id;
create or replace view public.hsd_v_price_entries as select p.*,c.code category_code,c.commercial_name_fr category_name from public.hsd_price_entries p join public.hsd_service_categories c on c.id=p.category_id;
create or replace view public.hsd_v_category_readiness as
with scores as (
 select c.*,
 least(100,(select count(*)*35 from public.hsd_doctrine_rules d where d.category_id=c.id and d.status in('draft','review','approved','active')))::int doctrine_readiness,
 case when exists(select 1 from public.hsd_capacity_rules x where x.category_id=c.id) then 100 else 0 end::int capacity_readiness,
 least(100,(select count(*)*20 from public.hsd_activity_library a where a.tenant_id=c.tenant_id and (cardinality(a.category_codes)=0 or c.code=any(a.category_codes))))::int activity_readiness,
 least(100,(select count(*)*25 from public.hsd_service_competency_rules x where x.category_id=c.id))::int staffing_readiness,
 least(100,(select count(*)*25 from public.hsd_safeguards s where s.category_id=c.id)+(select count(*)*4 from public.hsd_risk_controls r where r.tenant_id=c.tenant_id))::int safety_readiness,
 least(100,case when exists(select 1 from public.hsd_checklist_templates t where t.category_id=c.id) then 50 else 0 end + case when exists(select 1 from public.hsd_report_templates t where t.category_id=c.id) then 50 else 0 end)::int quality_readiness,
 least(100,case when exists(select 1 from public.hsd_price_entries p where p.category_id=c.id) then 50 else 0 end + least(50,(select count(*)*15 from public.hsd_service_options o where o.category_id=c.id)))::int commercial_readiness
 from public.hsd_service_categories c
), final as (select s.*,round((doctrine_readiness+capacity_readiness+activity_readiness+staffing_readiness+safety_readiness+quality_readiness+commercial_readiness)/7.0)::int overall_readiness from scores s)
select f.*,sf.code family_code,sf.name_fr family_name,sf.sort_order family_sort_order,array_remove(array[case when doctrine_readiness=0 then 'Doctrine manquante' end,case when capacity_readiness=0 then 'Capacité manquante' end,case when staffing_readiness=0 then 'Compétences non reliées' end,case when quality_readiness=0 then 'Checklist et rapport manquants' end,case when safety_readiness<60 then 'Safeguarding à renforcer' end],null) blockers from final f join public.hsd_service_families sf on sf.id=f.family_id;
create or replace view public.hsd_v_service_families as select sf.*,count(c.id)::int category_count,coalesce(round(avg(r.overall_readiness)),0)::int readiness_score from public.hsd_service_families sf left join public.hsd_service_categories c on c.family_id=sf.id left join public.hsd_v_category_readiness r on r.id=c.id group by sf.id;

do $$ declare t text; begin
 foreach t in array array['hsd_service_families','hsd_service_categories','hsd_service_subcategories','hsd_service_references','hsd_dossier_sections','hsd_doctrine_rules','hsd_capacity_rules','hsd_service_options','hsd_materials','hsd_competencies','hsd_risk_controls','hsd_activity_library','hsd_checklist_templates','hsd_report_templates','hsd_price_books','hsd_price_entries','hsd_saved_views'] loop
  execute format('drop trigger if exists %I on public.%I','trg_'||t||'_touch',t);
  execute format('create trigger %I before update on public.%I for each row execute function public.hsd_touch_updated_at()','trg_'||t||'_touch',t);
 end loop;
 foreach t in array array['hsd_service_families','hsd_service_categories','hsd_service_subcategories','hsd_service_references','hsd_service_versions','hsd_dossier_sections','hsd_doctrine_rules','hsd_capacity_rules','hsd_service_options','hsd_materials','hsd_service_material_links','hsd_competencies','hsd_service_competency_rules','hsd_risk_controls','hsd_safeguards','hsd_activity_library','hsd_checklist_templates','hsd_checklist_template_items','hsd_report_templates','hsd_report_template_fields','hsd_price_books','hsd_price_entries','hsd_option_sets','hsd_option_values','hsd_saved_views','hsd_comments','hsd_attachments','hsd_approvals','hsd_audit_events','hsd_outbox_events','hsd_configuration_imports','hsd_configuration_import_rows','hsd_configuration_import_issues','hsd_configuration_import_changes'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from anon, authenticated',t);
  execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;
drop trigger if exists trg_hsd_audit_immutable on public.hsd_audit_events;
